// Obtener workflows del input
const input = $input.all()[0].json;
let workflows = [];

if (input.data && Array.isArray(input.data)) {
  workflows = input.data;
}

// Ordenar workflows alfabéticamente por nombre
workflows.sort((a, b) => {
  const nameA = (a.name || '').toLowerCase();
  const nameB = (b.name || '').toLowerCase();
  return nameA.localeCompare(nameB);
});

// Construir la URL del POST
const webhookUrl = $execution.resumeUrl || '';
let baseUrl = '';
let postUrl = '';

if (webhookUrl) {
  const urlMatch = webhookUrl.match(/(https?:\/\/[^\/]+)/);
  if (urlMatch) {
    baseUrl = urlMatch[1];
    postUrl = baseUrl + '/webhook/deployment-submit';
  }
}

if (!postUrl) {
  postUrl = '/webhook/deployment-submit';
}

console.log('Base URL:', baseUrl);
console.log('POST URL final:', postUrl);

// Generar HTML
const html = `
<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Despliegue QA a Produccion</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            padding: 20px;
            display: flex;
            justify-content: center;
            align-items: center;
        }
        .container {
            background: white;
            border-radius: 20px;
            box-shadow: 0 20px 60px rgba(0,0,0,0.3);
            max-width: 900px;
            width: 100%;
            padding: 40px;
            animation: slideIn 0.5s ease-out;
        }
        @keyframes slideIn {
