</head>
<body>
    <div class="loading" id="loading">
        <div class="loading-content">
            <div class="spinner"></div>
            <h3>Desplegando...</h3>
            <p>Por favor espera mientras se despliegan los workflows a Produccion</p>
        </div>
    </div>

    <div class="container">
        <h1>Despliegue QA a Produccion</h1>
        <p class="subtitle">Sistema de Despliegue Automatizado de Workflows</p>

        <div class="warning">
            <p><strong>Importante:</strong> Los workflows seran creados en estado INACTIVO en el ambiente de produccion.</p>
        </div>

        <form id="deploymentForm">
            <div class="section">
                <div class="section-title">
                    <span>Workflows Disponibles</span>
                    <span class="badge">${workflows.length}</span>
                </div>

                ${workflows.length > 0 ? `
                    <div class="select-all">
                        <input type="checkbox" id="selectAllWorkflows" onchange="toggleAllWorkflows(this)">
                        <label for="selectAllWorkflows">Seleccionar todos los workflows</label>
                    </div>
                    <div class="items-grid">
                        ${workflows.map(wf => `
                            <label class="item-card">
                                <input type="checkbox" name="workflows" value="${wf.id}" class="workflow-checkbox">
                                <div class="item-info">
                                    <div class="item-name">${wf.name}</div>
                                    <div class="item-meta">
                                        ID: <span class="item-id">${wf.id}</span>
                                        ${wf.active ? ' • <span style="color: #48bb78;">Activo</span>' : ' • <span style="color: #a0aec0;">Inactivo</span>'}
                                    </div>
                                </div>
                            </label>
                        `).join('')}
                    </div>
                ` : `
                    <div class="empty-state">
                        <div class="empty-state-icon">-</div>
                        <p>No se encontraron workflows en QA</p>
                    </div>
                `}
            </div>

            <div class="actions">
                <button type="button" class="btn-secondary" onclick="window.location.reload()">
                    Recargar
                </button>
                <button type="submit" class="btn-primary" id="submitBtn">
                    Desplegar a Produccion
                </button>
            </div>
        </form>
    </div>

    <script>
        const POST_URL = '${postUrl}';
        console.log('POST URL configurada:', POST_URL);

        function toggleAllWorkflows(checkbox) {
            const workflowCheckboxes = document.querySelectorAll('.workflow-checkbox');
            workflowCheckboxes.forEach(cb => cb.checked = checkbox.checked);
        }

        document.getElementById('deploymentForm').addEventListener('submit', async function(e) {
            e.preventDefault();

            const formData = new FormData(this);
            const workflows = formData.getAll('workflows');

            if (workflows.length === 0) {
                alert('Por favor selecciona al menos un workflow para desplegar.');
                return;
            }

            if (!confirm(\`Estas seguro de desplegar \${workflows.length} workflow(s) a Produccion?\`)) {
                return;
            }

            document.getElementById('loading').classList.add('active');
            document.getElementById('submitBtn').disabled = true;

            const payload = {
                workflows: workflows
            };

            console.log('Enviando payload:', payload);
            console.log('A la URL:', POST_URL);

            try {
                const response = await fetch(POST_URL, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(payload)
                });

                console.log('Response status:', response.status);

                if (!response.ok) {
                    throw new Error(\`HTTP error! status: \${response.status}\`);
                }

                const html = await response.text();
                document.open();
                document.write(html);
                document.close();
            } catch (error) {
                console.error('Error completo:', error);
                document.getElementById('loading').classList.remove('active');
                document.getElementById('submitBtn').disabled = false;
                alert(\`Error al realizar el despliegue: \${error.message}\\n\\nURL intentada: \${POST_URL}\\n\\nVerifica que el workflow de despliegue este activo.\`);
            }
        });
    </script>
</body>
