`;

return [{ json: { html } }];

const webhookData = $('Webhook POST - Recibir Seleccion').first().json;
const selectedWorkflows = webhookData.body.workflows || [];

const qaWorkflows = $input.all().map(item => item.json);

if (!selectedWorkflows || selectedWorkflows.length === 0) {
  return [];
}

const workflowsToDeploy = qaWorkflows.filter(wf => 
  selectedWorkflows.includes(wf.id)
);

console.log(`Workflows seleccionados para desplegar: ${workflowsToDeploy.length}`);

return workflowsToDeploy.map(wf => ({ json: wf }));

// Obtener todos los workflows que llegan al nodo
const inputWorkflows = $input.all().map(item => JSON.parse(JSON.stringify(item.json)));

function removeEmojis(str) {
  return str
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, '')
    .replace(/[\u{2600}-\u{26FF}]/gu, '')
    .replace(/[\u{2700}-\u{27BF}]/gu, '')
    .replace(/[\u{FE00}-\u{FE0F}]/gu, '')
    .replace(/[\u{1F900}-\u{1F9FF}]/gu, '')
    .replace(/[\u{1F300}-\u{1F5FF}]/gu, '')
    .replace(/[\u{1F680}-\u{1F6FF}]/gu, '')
    .replace(/[\u{1F1E0}-\u{1F1FF}]/gu, '')
    .trim()
    .replace(/\s+/g, ' ');
}

// Procesar cada workflow y devolver un item por cada uno
const processed = inputWorkflows.map(workflow => {
  const originalName = workflow.name;
  const originalQaId = workflow.id;

  // Eliminar campos problematicos
  delete workflow.id;
  delete workflow.createdAt;
  delete workflow.updatedAt;
  delete workflow.versionId;
  delete workflow.error;
  delete workflow.shared;
  delete workflow.triggerCount;
  delete workflow.isArchived;

  workflow.name = removeEmojis(workflow.name);
  workflow._originalQaId = originalQaId;
  workflow.active = false;

  console.log(`Preparado: ${originalName} -> ${workflow.name}`);

  return { json: workflow };
});

return processed;

// Obtener todos los workflows preparados
const preparedWorkflows = $('Preparar Workflow Individual').all().map(item => item.json);

// Obtener todos los workflows existentes en produccion
const prodWorkflows = $input.all().map(item => item.json);

console.log(`Workflows preparados: ${preparedWorkflows.length}`);
console.log(`Workflows en produccion: ${prodWorkflows.length}`);

// Para cada workflow preparado, determinar si existe o no
const result = preparedWorkflows.map(qaWorkflow => {
  const targetName = qaWorkflow.name;
  const existingWf = prodWorkflows.find(wf => wf.name === targetName);

  if (existingWf) {
    console.log(`Workflow existe: "${targetName}" (ID: ${existingWf.id})`);
  } else {
    console.log(`Workflow nuevo: "${targetName}"`);
  }

  return {
    json: {
      ...qaWorkflow,
      _metadata: {
        existingWfId: existingWf ? existingWf.id : null,
        shouldUpdate: !!existingWf,
        workflowName: targetName
      }
    }
  };
});

return result;

// LIMPIAR METADATA PARA CREATE
// Procesar todos los workflows que llegan
const allWorkflows = $input.all();

const cleaned = allWorkflows.map(item => {
  const dirtyWorkflow = item.json;

  // Preservar _originalQaId temporalmente
  const originalQaId = dirtyWorkflow._originalQaId;

  const cleanWorkflow = {
    name: dirtyWorkflow.name,
    nodes: dirtyWorkflow.nodes,
    connections: dirtyWorkflow.connections,
    active: dirtyWorkflow.active || false
  };

  // Solo agregar tags si existen y no está vacío
  if (dirtyWorkflow.tags && Array.isArray(dirtyWorkflow.tags) && dirtyWorkflow.tags.length > 0) {
    cleanWorkflow.tags = dirtyWorkflow.tags;
  }

  // Para CREATE, solo incluir executionOrder en settings (sin callerPolicy)
  if (dirtyWorkflow.settings && dirtyWorkflow.settings.executionOrder) {
    cleanWorkflow.settings = {
      executionOrder: dirtyWorkflow.settings.executionOrder
    };
  }

  // NO incluir: pinData, staticData, meta - causan problemas en CREATE

  // Agregar _originalQaId de vuelta (para rastreo)
  cleanWorkflow._originalQaId = originalQaId;

  console.log('Workflow limpiado para CREATE:', cleanWorkflow.name);
  console.log('Settings enviados:', JSON.stringify(cleanWorkflow.settings || {}));

  return { json: cleanWorkflow };
});

return cleaned;

const webhookData = $('Webhook POST - Recibir Seleccion').first().json;
const selectedWorkflowsIds = webhookData.body.workflows || [];

// Obtener todos los workflows originales de QA con sus IDs
const qaWorkflows = $('Filtrar Workflows').all().map(item => ({
  qaId: item.json.id,
  name: item.json.name
}));

// CRÍTICO: Obtener TODOS los resultados de TODAS las ejecuciones previas
const allResults = $input.all();

console.log('=== INICIO ANALISIS DE RESULTADOS ===');
console.log('Workflows seleccionados:', selectedWorkflowsIds.length);
console.log('Workflows QA originales:', qaWorkflows.length);
console.log('Resultados recibidos en TODAS las ejecuciones:', allResults.length);

// Crear un mapa de workflows desplegados exitosamente
const deploymentResults = new Map();

allResults.forEach((item, index) => {
  const json = item.json;

  console.log(`Resultado ${index}:`, {
    name: json.name,
    id: json.id,
    hasError: !!(json.error || json.statusCode >= 400),
    _originalQaId: json._originalQaId,
    _deployAction: json._deployAction
  });

  // Determinar si es exitoso o error
  const hasError = !!(json.error || (json.statusCode && json.statusCode >= 400));

  if (!hasError && json.id) {
    // Exitoso
    const qaId = json._originalQaId;
    const action = json._deployAction || 'Creado';

    deploymentResults.set(qaId || json.name, {
      qaId: qaId,
      prodId: json.id,
      name: json.name,
      action: action,
      status: 'success',
      error: null
    });

    console.log(`✓ Exitoso: ${json.name} (${action})`);
  } else {
    // Error
    const qaId = json._originalQaId;
    const errorMsg = json.error?.message || json.message || JSON.stringify(json.error) || 'Error desconocido';

    deploymentResults.set(qaId || json.name, {
      qaId: qaId,
      prodId: null,
      name: json.name || 'Desconocido',
      action: 'Error',
      status: 'error',
      error: errorMsg
    });

    console.log(`✗ Fallido: ${json.name || 'Desconocido'} - ${errorMsg}`);
  }
});

// Crear el reporte final basado en los workflows originales
const workflowResults = qaWorkflows.map(qaWf => {
  const result = deploymentResults.get(qaWf.qaId) || deploymentResults.get(qaWf.name);

  if (result) {
    return result;
  } else {
    // No se encontro resultado, marcar como fallido
    console.log(`⚠ Sin resultado: ${qaWf.name}`);
    return {
      qaId: qaWf.qaId,
      prodId: null,
      name: qaWf.name,
      action: 'Error',
      status: 'error',
      error: 'No se pudo procesar el workflow'
    };
  }
});

const successfulWorkflows = workflowResults.filter(w => w.status === 'success').length;
const failedWorkflows = workflowResults.filter(w => w.status === 'error').length;
const createdWorkflows = workflowResults.filter(w => w.action === 'Creado' && w.status === 'success').length;
const updatedWorkflows = workflowResults.filter(w => w.action === 'Actualizado' && w.status === 'success').length;

const report = {
  timestamp: new Date().toISOString(),
  summary: {
    workflows: {
      selected: selectedWorkflowsIds.length,
      total: workflowResults.length,
      successful: successfulWorkflows,
      failed: failedWorkflows,
      created: createdWorkflows,
      updated: updatedWorkflows,
      successRate: workflowResults.length > 0 
        ? ((successfulWorkflows / workflowResults.length) * 100).toFixed(1)
        : '0'
    }
  },
  details: {
    workflows: workflowResults
  }
};

console.log('\n' + '='.repeat(60));
console.log('REPORTE FINAL');
console.log('='.repeat(60));
console.log(`Workflows Seleccionados: ${selectedWorkflowsIds.length}`);
console.log(`Workflows Procesados: ${workflowResults.length}`);
console.log(`Workflows Exitosos: ${successfulWorkflows}`);
console.log(`Workflows Fallidos: ${failedWorkflows}`);
console.log(`Workflows Creados: ${createdWorkflows}`);
console.log(`Workflows Actualizados: ${updatedWorkflows}`);
console.log('='.repeat(60));

return [{ json: report }];

const report = $json;

const html = `
