(() => {
  function rand(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  let ip;
  while (true) {
    const o1 = rand(1, 223); // evita 0 y >223 (multicast/reservado)
    const o2 = rand(0, 255);
    const o3 = rand(0, 255);
    const o4 = rand(1, 254); // evita 0 y 255 (red y broadcast)

    // filtrar rangos privados
    if (
      o1 === 10 || // 10.0.0.0/8
      (o1 === 172 && o2 >= 16 && o2 <= 31) || // 172.16.0.0/12
      (o1 === 192 && o2 === 168) || // 192.168.0.0/16
      o1 === 127 || // loopback
      (o1 === 169 && o2 === 254) // APIPA
    ) {
      continue;
    }

    ip = `${o1}.${o2}.${o3}.${o4}`;
    break;
  }
  return ip;
})()
}}

