// Script para n8n - Consolida múltiples items de videos de TikTok en un solo texto
// Une todos los items de entrada en un texto unificado

// Obtener todos los items de entrada
const allItems = $input.all();

// Verificar que tengamos items
if (!allItems || allItems.length === 0) {
  return [{
    json: { 
      texto_consolidado: "No se encontraron videos para procesar",
      total_videos: 0
    }
  }];
}

// Crear el texto consolidado
let textoConsolidado = '';

allItems.forEach((item, index) => {
  const numeroVideo = index + 1;
  const videoData = item.json;

  textoConsolidado += `Video ${numeroVideo}:\n`;
  textoConsolidado += `Descripción: ${videoData.descripcion_video || 'No disponible'}\n`;
  textoConsolidado += `Transcripción: ${videoData.subtitulos_video || 'No disponible'}\n\n`;
});

// Remover el último salto de línea doble
textoConsolidado = textoConsolidado.trim();

// Retornar el texto consolidado como un solo item
return [{
  json: { 
    texto_consolidado: textoConsolidado,
    total_videos: allItems.length
  }
}];

